<script setup lang="ts">
import { computed, ref, watch } from 'vue'
import { filterIssues, issueDeadline } from '@/lib/issueTracking'
import { usePmisStore, ROLES, defaultWork, safeReference, type WorkStatus, type Issue, parsePmisBackup, mergePmis, type State } from '@/stores/pmis'
import plan from '@/data/assessmentPlan.json'
import { PARTS } from '@/data/parts'
const props=defineProps<{mode:string;target?:string}>()
const emit=defineEmits<{openTask:[code:string];openDocument:[code:string];openAsset:[id:string];openInspections:[]}>()
const pm=usePmisStore(), notice=ref(''), failure=ref(false), filter=ref('全部'), search=ref(''), mine=ref(false)
const task=computed(()=>plan.tasks.find(t=>t.code===props.target))
const asset=computed(()=>PARTS.find(p=>p.id===props.target))
const assetTasks=computed(()=>plan.tasks.filter(t=>pm.taskParts(t.code).includes(asset.value?.id??'')).map(t=>t.code))
const document=computed(()=>plan.documents.find(d=>d.code===props.target))
const work=ref(defaultWork()), reviewNote=ref(''), commentText=ref('')
const issueDraft=ref({title:'',type:'RFI',priority:'一般',owner:'',due:'',task:'',asset:'',document:'',description:''})
const binding=ref<string[]>([]), bindingReason=ref('')
const incoming=ref<State|null>(null), backupSummary=ref(''), backupInput=ref<HTMLInputElement|null>(null)
const workFilter=ref('全部')
const workRows=computed(()=>plan.tasks.map(t=>({...t,...(pm.state.work[t.code]??{status:'未開始',due:'',owner:t.owner,reviewer:''})})).filter(t=>(workFilter.value==='全部'||workFilter.value==='逾期'?workFilter.value!=='逾期'||overdue(t.due)&&t.status!=='已接受':t.status===workFilter.value)&&(!mine.value||!!pm.actor.trim()&&(t.owner.includes(pm.actor.trim())||t.reviewer.includes(pm.actor.trim())))))
async function readBackup(e:Event){incoming.value=null;backupSummary.value='';const input=e.target as HTMLInputElement;try{const file=input.files?.[0];if(!file)return;if(file.size>5_000_000)throw new Error('備份不可超過 5 MB');const parsed=parsePmisBackup(await file.text(),pm.project);mergePmis(pm.state,parsed);incoming.value=parsed;backupSummary.value=`工作 ${Object.keys(parsed.work).length} 項、關聯 ${Object.keys(parsed.bindings).length} 項、查驗 ${parsed.inspections.length} 筆、會議 ${parsed.meetings.length} 筆、議題 ${parsed.issues.length} 筆、文件版本 ${parsed.revisions.length} 筆。相同紀錄略過，只新增未存在資料。`;failure.value=false;notice.value='備份檢查通過，請檢閱後按確認合併。'}catch(err){failure.value=true;notice.value=err instanceof Error?err.message:'讀取失敗'}finally{input.value=''}}
const revision=ref({version:'',title:'',url:''})
const responses=ref<Record<string,string>>({})
const targetKey=computed(()=>`${props.mode}:${props.target??'project'}`)
watch(()=>[props.mode,props.target],()=>{notice.value='';binding.value=[...pm.taskParts(props.target??'')];bindingReason.value='';work.value={...(pm.state.work[props.target??'']??defaultWork())};reviewNote.value='';commentText.value='';issueDraft.value={title:'',type:'RFI',priority:'一般',owner:'',due:'',task:props.mode==='task'?props.target??'':'',asset:props.mode==='asset'?props.target??'':'',document:props.mode==='document'?props.target??'':'',description:''};revision.value={version:'',title:'',url:''}},{immediate:true})
function run(fn:()=>void){try{fn();failure.value=!!pm.error;notice.value=pm.error||'已更新本機紀錄。'}catch(e){failure.value=true;notice.value=e instanceof Error?e.message:'操作失敗'}}
const issueOwner=ref(''), issuePriority=ref('全部'), issueDue=ref('全部'), issueTask=ref('')
const today=()=>new Date().toLocaleDateString('sv-SE')
const scopedIssues=computed(()=>pm.state.issues.filter(i=>props.mode==='issue'?i.id===props.target:props.mode==='task'?i.task===props.target:props.mode==='asset'?i.asset===props.target:props.mode==='document'?i.document===props.target:true))
const issueOwners=computed(()=>[...new Set(scopedIssues.value.map(i=>i.owner))].sort())
const issues=computed(()=>props.mode==='issue'?scopedIssues.value:filterIssues(scopedIssues.value.filter(i=>!mine.value||!!pm.actor.trim()&&i.owner.includes(pm.actor.trim())),{status:filter.value,search:search.value,owner:issueOwner.value,priority:issuePriority.value,due:issueDue.value,task:issueTask.value},today()))
function resetIssueFilters(){filter.value='全部';search.value='';issueOwner.value='';issuePriority.value='全部';issueDue.value='全部';issueTask.value='';mine.value=false}
function exportIssues(){const url=URL.createObjectURL(new Blob([JSON.stringify({project:pm.project,exportedAt:new Date().toISOString(),scope:'目前篩選的本機議題，非正式簽認',issues:issues.value},null,2)],{type:'application/json'}));const a=window.document.createElement('a');a.href=url;a.download=`${pm.project}-issues.json`;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)}

const comments=computed(()=>pm.state.comments.filter(c=>c.target===targetKey.value))
const revisions=computed(()=>pm.state.revisions.filter(r=>r.code===props.target))
const reviews=computed(()=>Object.entries(pm.state.work).filter(([,w])=>w.status==='待審查'&&(!mine.value||!!pm.actor.trim()&&w.reviewer.includes(pm.actor.trim()))))
const roleHint=computed(()=>({'太電 PMO':'整合工作、跨單位問題與合併審查','業主決策人':'掌握重大議題、待決條件與接受紀錄','PISG 商務':'追蹤正式提交、合約介面與未結事項','HPE 顧問':'編製成果、技術回覆與跨專業整合','承包商／供應商':'追蹤交付、現場問題與資料需求','品管／試運轉':'核對成果證據、缺失與查驗條件','維運':'追蹤可維護性、移交與設備資料'}[pm.role]))
function overdue(d:string){return !!d&&d<new Date().toLocaleDateString('sv-SE')}
function exportData(){const url=URL.createObjectURL(new Blob([JSON.stringify({project:pm.project,...pm.state},null,2)],{type:'application/json'}));const a=window.document.createElement('a');a.href=url;a.download=`${pm.project}-pmis-backup.json`;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)}
function nextWork(s:WorkStatus):WorkStatus[]{return s==='未開始'||s==='退回修訂'?['執行中']:s==='執行中'?['待審查']:s==='待審查'?['已接受','退回修訂']:['退回修訂']}
function nextIssue(s:Issue['status']):Issue['status'][]{return s==='待處理'?['處理中']:s==='處理中'?['待確認']:s==='待確認'?['已結案','處理中']:['處理中']}
</script>
<template>
<div class="pmis">
 <div class="identity"><label>角色視角<select v-model="pm.role"><option v-for="r in ROLES" :key="r">{{r}}</option></select></label><label>操作人<input v-model="pm.actor" placeholder="輸入姓名以記錄操作" /></label><button @click="exportData">匯出備份</button><button @click="backupInput?.click()">還原備份</button><input ref="backupInput" type="file" accept=".json,application/json" hidden @change="readBackup" /></div>
 <p class="local">本機協作試用 · 角色切換僅供檢視，不代表身分驗證或授權。紀錄只存此瀏覽器，尚未多人同步；接受紀錄不構成正式合約驗收。</p>
 <article v-if="incoming"><b>備份合併預覽</b><p>{{backupSummary}}</p><button @click="run(()=>{pm.mergeBackup(incoming!);incoming=null})">確認合併（不覆寫）</button><button @click="incoming=null">取消</button></article><p v-if="pm.error" class="error" role="alert">{{pm.error}}</p><p v-if="notice" :class="failure?'error':'success'" role="status">{{notice}}</p>
 <template v-if="mode==='home'"><h2>{{pm.role}}工作台</h2><p>{{roleHint}}</p><div class="metrics"><div><b>{{pm.pending.length}}</b>未結議題</div><div><b>{{pm.pending.filter(i=>overdue(i.due)).length}}</b>逾期議題</div><div><b>{{reviews.length}}</b>待審查工作</div><div><b>{{pm.state.revisions.filter(r=>r.status==='待審查').length}}</b>待審文件版本</div></div><label class="check"><input type="checkbox" v-model="mine" />只看與操作人姓名相符的議題／工作審查</label><button @click="emit('openInspections')">查驗待複核 {{pm.state.inspections.filter(i=>i.status==='待複核').length}} 筆 → 查驗與缺失</button><h3>工作進度與期限追蹤</h3><p>已接受 {{Object.values(pm.state.work).filter(w=>w.status==='已接受').length}} / {{plan.tasks.length}} 項。此為工作項目數，非工程完成百分比；未設定日期不判定逾期。</p><select v-model="workFilter" aria-label="工作狀態篩選"><option v-for="s in ['全部','逾期','未開始','執行中','待審查','已接受','退回修訂']" :key="s">{{s}}</option></select><div class="work-list"><button v-for="t in workRows" :key="t.code" class="row-link" @click="emit('openTask',t.code)">{{t.code}} · {{t.name}}<small>{{t.status}} · {{t.owner||'待指派'}} · <span :class="{error:overdue(t.due)&&t.status!=='已接受'}">{{t.due||'未設定期限'}}</span></small></button><p v-if="!workRows.length">沒有符合篩選的工作。</p></div><h3>工作審查待辦</h3><p v-if="!reviews.length">目前沒有符合條件的待審工作。先從 WBS 設定主責與完成條件，再提交成果。</p><button v-for="[code,w] in reviews" :key="code" class="row-link" @click="emit('openTask',code)">{{code}} · {{plan.tasks.find(t=>t.code===code)?.name}}<small>{{w.owner}} → {{w.reviewer}} · {{w.due||'未設定期限'}}</small></button><h3>待審文件版本</h3><button v-for="r in pm.state.revisions.filter(r=>r.status==='待審查')" :key="r.id" class="row-link" @click="emit('openDocument',r.code)">{{r.code}} · {{r.version}} · {{r.title}}</button></template>
 <template v-if="mode==='task'&&task"><h2>{{task.code}} · {{task.name}}</h2><p>來源主責：{{task.owner}}｜{{task.basis}}{{task.start}}–{{task.end}}｜來源第 {{task.page}} 頁</p><span class="badge">{{pm.state.work[task.code]?.status??'未開始'}}</span><form @submit.prevent="run(()=>pm.saveWork(task!.code,work))" class="form-grid"><label>具名主責<input v-model="work.owner" required /></label><label>具名審查人<input v-model="work.reviewer" /></label><label>協作追蹤期限（不改來源工作日）<input type="date" v-model="work.due" /></label><label class="wide">完成／接受條件<textarea v-model="work.criteria" placeholder="須交付的成果、檢查方式與接受條件" /></label><label class="wide">成果證據／文件編號與版本<textarea v-model="work.evidence" placeholder="填寫文件版本、紀錄位置與完成說明" /></label><button type="submit">儲存工作設定</button></form><label>審查說明<textarea v-model="reviewNote" placeholder="接受或退回時必填" /></label><div class="actions"><button v-for="s in nextWork(pm.state.work[task.code]?.status??'未開始')" :key="s" @click="run(()=>{pm.transition(task!.code,s,reviewNote);work={...pm.state.work[task!.code]!}})">{{s==='執行中'?'開始／恢復工作':s==='待審查'?'提交審查':s==='已接受'?'記錄接受':'退回修訂'}}</button></div><details><summary>編輯 WBS ↔ 3D 評估關聯（{{pm.taskParts(task.code).length}} 組）</summary><p>調整後會同步至甘特圖及設備資料卡。此設定僅為評估參照，不改變安裝或驗收狀態。</p><div class="binding-grid"><label v-for="p in PARTS" :key="p.id" class="check"><input type="checkbox" v-model="binding" :value="p.id" />{{p.name}}</label></div><label>調整原因<textarea v-model="bindingReason" /></label><button @click="run(()=>pm.setBinding(task!.code,binding,bindingReason))">儲存關聯</button><button @click="run(()=>{pm.resetBinding(task!.code,bindingReason);binding=[...pm.taskParts(task!.code)]})">恢復預設關聯</button><small>取消全部勾選會明確設定此工項沒有模型關聯。</small></details><h3>關聯交付文件</h3><button v-for="code in task.documents" :key="code" @click="emit('openDocument',code)">{{code}}</button></template>
 <template v-if="mode==='asset'&&asset"><h2>{{asset.name}}</h2><dl><dt>模型群組 ID</dt><dd>{{asset.id}}</dd><dt>系統</dt><dd>{{asset.group}}</dd><dt>模型版本</dt><dd>video-detail-v2</dd><dt>資料可信度</dt><dd>概念幾何，設備選型及現場驗證待確認</dd></dl><p>目前資料卡管理模型群組；不是單一設備履歷。實體序號、保固、額定容量與驗收資料尚未建立。</p><button @click="emit('openAsset',asset.id)">在 3D 定位</button><h3>關聯評估工作</h3><button v-for="code in assetTasks" :key="code" @click="emit('openTask',code)">{{code}} · {{plan.tasks.find(t=>t.code===code)?.name}}</button></template>
 <template v-if="mode==='document'&&document"><h2>{{document.code}} · {{document.name}}</h2><p>{{document.scope}}</p><p>{{document.owner}} · {{document.due}} · {{document.format}}</p><p v-if="document.optional" class="warning">另行選配文件：登錄版本不代表已委任或納入基本驗收。</p><h3>登錄文件版本</h3><form @submit.prevent="run(()=>{pm.addRevision({code:document!.code,...revision});revision={version:'',title:'',url:''}})" class="form-grid"><label>版本<input v-model="revision.version" required placeholder="例如 Rev A" /></label><label>修訂說明<input v-model="revision.title" required /></label><label class="wide">文件連結<input v-model="revision.url" type="url" required placeholder="https://…" /></label><button>登錄版本</button></form><small>僅儲存連結與版本資料，不上傳檔案，不檢驗連結的存取權。文件內容請由有權限人員確認。</small><label>版本審查說明<textarea v-model="reviewNote" /></label><article v-for="r in revisions" :key="r.id"><b>{{r.version}} · {{r.status}}</b><p>{{r.title}}</p><small>{{r.author}} · {{new Date(r.createdAt).toLocaleString()}}</small><a v-if="safeReference(r.url)" :href="r.url" target="_blank" rel="noopener noreferrer">開啟此版本文件 ↗</a><p>{{r.note}}</p><button v-for="s in nextWork(r.status)" :key="s" @click="run(()=>pm.reviewRevision(r.id,s,reviewNote))">{{s}}</button></article><p v-if="!revisions.length">尚未登錄版本。</p></template>
 <template v-if="['home','issues','issue','task','asset','document'].includes(mode)"><h3>{{mode==='home'?'議題待辦':'議題與跨單位協調'}}</h3><div v-if="mode!=='issue'" class="filters"><input v-model="search" aria-label="搜尋議題" placeholder="搜尋議題、責任人或關聯編號" /><label>狀態<select v-model="filter" aria-label="議題狀態"><option v-for="s in ['全部','待處理','處理中','待確認','已結案']" :key="s">{{s}}</option></select></label><label>責任窗口<select v-model="issueOwner" aria-label="責任窗口篩選"><option value="">全部責任窗口</option><option v-for="owner in issueOwners" :key="owner">{{owner}}</option></select></label><label>優先級<select v-model="issuePriority" aria-label="優先級篩選"><option v-for="p in ['全部','一般','高','緊急']" :key="p">{{p}}</option></select></label><label>期限<select v-model="issueDue" aria-label="期限篩選"><option v-for="d in ['全部','逾期','今日到期','尚未到期','未設定期限','已結案']" :key="d">{{d}}</option></select></label><label>關聯工作<select v-model="issueTask" aria-label="關聯工作篩選"><option value="">全部關聯工作</option><option v-for="t in plan.tasks" :key="t.code" :value="t.code">{{t.code}} {{t.name}}</option></select></label><button @click="resetIssueFilters">清除議題篩選</button></div><div class="actions"><span>顯示 {{issues.length}} / {{scopedIssues.length}} 筆 · 未結案優先，依期限排列</span><button @click="exportIssues">匯出目前議題</button></div><p v-if="!issues.length">{{mode==='issue'?'找不到指定議題；可能已切換專案或尚未匯入該筆資料。':'沒有符合條件的議題。'}}</p><article v-for="i in issues" :key="i.id"><div class="issue-head"><b>{{i.id}} · {{i.title}}</b><span class="badge">{{i.status}}</span></div><small>{{i.type}} · {{i.priority}} · {{i.owner}} · <span :class="{error:overdue(i.due)&&i.status!=='已結案'}">{{i.due?`${i.due} · `:''}}{{issueDeadline(i,today())}}</span></small><p>{{i.description}}</p><div class="actions"><button v-if="i.task" @click="emit('openTask',i.task)">WBS {{i.task}}</button><button v-if="i.asset" @click="emit('openAsset',i.asset)">3D {{i.asset}}</button><button v-if="i.document" @click="emit('openDocument',i.document)">{{i.document}}</button></div><p v-if="i.response">最近回覆：{{i.response}}</p><label>處理／確認說明<textarea v-model="responses[i.id]" /></label><button v-for="s in nextIssue(i.status)" :key="s" @click="run(()=>pm.moveIssue(i.id,s,responses[i.id]??''))">{{s==='處理中'?(i.status==='待處理'?'開始處理':'重新處理'):s==='待確認'?'提交處理結果':'確認結案'}}</button></article>
 <details v-if="mode!=='issue'" :open="mode==='issues'"><summary>＋ 建立議題／RFI／風險／待決事項</summary><form @submit.prevent="run(()=>{pm.createIssue(issueDraft);issueDraft={...issueDraft,title:'',description:''}})" class="form-grid"><label class="wide">議題標題<input v-model="issueDraft.title" required /></label><label>類型<select v-model="issueDraft.type"><option v-for="s in ['RFI','缺失','風險','變更','待決事項']" :key="s">{{s}}</option></select></label><label>優先級<select v-model="issueDraft.priority"><option>一般</option><option>高</option><option>緊急</option></select></label><label>具名責任窗口<input v-model="issueDraft.owner" required /></label><label>回覆期限<input type="date" v-model="issueDraft.due" /></label><label>關聯 WBS<select v-model="issueDraft.task"><option value="">未關聯</option><option v-for="t in plan.tasks" :key="t.code" :value="t.code">{{t.code}} {{t.name}}</option></select></label><label>模型群組<select v-model="issueDraft.asset"><option value="">未關聯</option><option v-for="p in PARTS" :key="p.id" :value="p.id">{{p.name}}</option></select></label><label>交付文件<select v-model="issueDraft.document"><option value="">未關聯</option><option v-for="d in plan.documents" :key="d.code">{{d.code}}</option></select></label><label class="wide">背景、影響與需要回覆的事項<textarea v-model="issueDraft.description" required /></label><button>建立議題</button></form></details></template>
 <template v-if="['task','asset','document'].includes(mode)"><h3>關聯查驗紀錄</h3><article v-for="i in pm.state.inspections.filter(i=>mode==='task'?i.task===target:mode==='asset'?i.asset===target:i.document===target)" :key="i.id"><b>{{i.title}} · {{i.status}}</b><small>{{i.inspector}} → {{i.reviewer}}</small><button @click="emit('openInspections')">前往查驗管理</button></article><h3>情境留言</h3><p v-if="!comments.length">尚無留言。</p><article v-for="c in comments" :key="c.id"><small>{{c.actor}} · {{new Date(c.at).toLocaleString()}}</small><p>{{c.text}}</p></article><form @submit.prevent="run(()=>{pm.comment(targetKey,commentText);commentText=''})"><label>新增留言<textarea v-model="commentText" required /></label><button>儲存留言</button></form></template>
 <details><summary>操作紀錄（{{pm.state.audit.length}}）</summary><article v-for="a in pm.state.audit.filter(a=>!target||a.target===target||a.target===targetKey||issues.some(i=>i.id===a.target)).slice(0,50)" :key="a.id"><b>{{a.target}} · {{a.action}}</b><small>{{a.actor}} · {{new Date(a.at).toLocaleString()}}</small><p>{{a.note}}</p></article><small>顯示最近 50 筆，完整資料可匯出；本機紀錄不是防竄改稽核系統。</small></details>
</div>
</template>
<style scoped>
.work-list{max-height:280px;overflow:auto;margin-top:10px}.binding-grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(180px,1fr));gap:6px}.binding-grid label{font-size:11px}

